mapper.select:
SELECT  FROM crm_youzan_event
WHERE tenant_id=#{tenantId} AND shop_id=#{shopId} AND id IN (
  SELECT MAX(id) FROM crm_youzan_event
  WHERE tenant_id=#{tenantId} AND shop_id=#{shopId}
  GROUP BY external_order_no
)

ORDER BY id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(DISTINCT external_order_no) FROM crm_youzan_event
WHERE tenant_id=#{tenantId} AND shop_id=#{shopId} AND id IN (
  SELECT MAX(id) FROM crm_youzan_event
  WHERE tenant_id=#{tenantId} AND shop_id=#{shopId}
  GROUP BY external_order_no
)

mapper.update:
UPDATE crm_youzan_event SET process_status=#{status},process_attempts=process_attempts+1,last_error=#{lastError},
  next_retry_at=#{nextRetryAt},processed_at=#{processedAt},order_id=#{orderId},version=version+1
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{version}

mapper.select:
SELECT  FROM crm_youzan_sync_issue WHERE tenant_id=#{tenantId}
AND status=#{status}
ORDER BY id DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE crm_youzan_sync_issue SET status=#{status},attempts=#{attempts},last_error=#{lastError},next_retry_at=#{nextRetryAt},
  resolved_at=#{resolvedAt},resolved_by=#{resolvedBy},version=version+1
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{version}
